/**
 * Reference checks shared by the service layer.
 *
 * A write does not only address the row it changes — it also points at other
 * rows: an assignee, a project lead, labels, a parent issue, the comment a
 * reply hangs under. Every one of those must be usable from the organization
 * the write is made in, and each service calls the matching guard here
 * *before* its first write, so a refused change leaves nothing behind.
 *
 * The outcome is the same for every kind of reference:
 *
 * - it belongs to another organization → `TenantScopeError`, raised through
 *   `assertOrgScope()` exactly like any other cross-tenant access;
 * - it does not exist, is archived, or is not usable from where the write
 *   lands (wrong project, wrong issue, a reply to a reply, not a current
 *   member) → `NotFoundError`.
 *
 * Must call (do not reimplement): assertOrgScope, isArchived
 */
import { isArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import { NotFoundError } from "./_support";
import type { Comment } from "@/types/comment";
import type {
  CommentId,
  IssueId,
  LabelId,
  OrgId,
  ProjectId,
  UserId,
} from "@/types/common";
import type { Issue } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Throws unless `userId` is a current member of the organization. Users are
 * global rows, so there is no "other tenant's user": a stranger, a member of
 * some other organization and a member who has left are all simply not found
 * here. `entity` names the role the user was offered for ("Assignee", …).
 */
export async function assertCurrentMember(
  orgId: OrgId,
  userId: UserId,
  entity: string,
): Promise<void> {
  const current = await memberRepo.findCurrentMemberUserIds(orgId, [userId]);
  if (!current.has(userId)) {
    throw new NotFoundError(entity, userId);
  }
}

/** Keeps the ids that are current members, in their original order. */
export async function onlyCurrentMembers(
  orgId: OrgId,
  userIds: readonly UserId[],
): Promise<readonly UserId[]> {
  const distinct = [...new Set(userIds)];
  const current = await memberRepo.findCurrentMemberUserIds(orgId, distinct);
  return distinct.filter((userId) => current.has(userId));
}

/**
 * Throws unless every label is one of the organization's own. Returns the
 * ids de-duplicated, in the order given — the join table holds one row per
 * (issue, label), so a repeated id must not reach it.
 */
export async function assertOwnLabels(
  actor: Actor,
  orgId: OrgId,
  labelIds: readonly LabelId[],
): Promise<readonly LabelId[]> {
  const distinct = [...new Set(labelIds)];
  if (distinct.length === 0) return distinct;

  const owners = await labelRepo.findLabelOwners(distinct);
  for (const labelId of distinct) {
    const owner = owners.get(labelId);
    if (owner === undefined) throw new NotFoundError("Label", labelId);
    assertOrgScope(actor, owner);
    if (owner !== orgId) throw new NotFoundError("Label", labelId);
  }

  return distinct;
}

/**
 * Loads the issue a new sub-issue will hang under: a live issue of the same
 * project. Anything else would be a parent nobody can see from the child.
 */
export async function requireParentIssue(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
  parentId: IssueId,
): Promise<Issue> {
  const parent = await issueRepo.findIssueById(orgId, parentId);
  if (parent === null) {
    const owner = await issueRepo.findIssueOwner(parentId);
    if (owner !== null) assertOrgScope(actor, owner);
    throw new NotFoundError("Parent issue", parentId);
  }

  if (parent.projectId !== projectId || isArchived(parent)) {
    throw new NotFoundError("Parent issue", parentId);
  }
  return parent;
}

/**
 * Loads the comment a reply will hang under: a live, top-level comment on the
 * same issue. Threads are one level deep, so a reply is never a valid anchor,
 * and a reply under a deleted or foreign comment would show in no thread.
 */
export async function requireReplyTarget(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
  parentId: CommentId,
): Promise<Comment> {
  const parent = await commentRepo.findCommentById(orgId, parentId);
  if (parent === null) {
    const owner = await commentRepo.findCommentOwner(parentId);
    if (owner !== null) assertOrgScope(actor, owner);
    throw new NotFoundError("Parent comment", parentId);
  }

  if (
    parent.issueId !== issueId ||
    parent.parentId !== null ||
    isArchived(parent)
  ) {
    throw new NotFoundError("Parent comment", parentId);
  }
  return parent;
}

